#!/usr/bin/bash
set -euo pipefail
export PATH=/usr/local/sbin:/usr/local/bin:/usr/bin
umask 077
fail() { printf 'pf-upstream-runtime-install: %s\n' "$*" >&2; exit 1; }
[[ $# == 0 && $(id -u) == 0 && $(uname -r) == 7.2.10-pf-console-r1 ]] || fail 'requires root on console-r1; no arguments'
[[ $(findmnt -n -o FSTYPE -T /) == overlay &&
   $(findmnt -n -o TARGET -T /run/pf-arch/state) == /run/pf-arch/state &&
   $(findmnt -n -o FSTYPE -T /run/pf-arch/state) == ext4 ]] || fail 'persistent overlay missing'
for directory in /run /run/lock /usr /usr/local /usr/local/sbin /var /var/lib /var/lib/pf-console-boot; do
    [[ -d $directory && ! -L $directory ]] || fail "unexpected directory $directory"
done
[[ ! -L /run/lock/pf-peripheral-stage.lock ]] || fail 'unexpected lock symlink'
exec 9>/run/lock/pf-peripheral-stage.lock
flock -n 9 || fail 'peripheral action is running'
[[ ! -e /var/lib/pf-console-boot/pending && ! -L /var/lib/pf-console-boot/pending ]] || fail 'unresolved hardware action'
target=/usr/local/sbin/pf-console-boot
[[ -f $target && ! -L $target && $(stat -c %u:%g "$target") == 0:0 ]] || fail 'unexpected helper target'
actual=$(sha256sum "$target"); actual=${actual%% *}
[[ $actual == 4b7ef11b27872998a6e8afd6bc01d425b0f8e95ccab085f8980ef259197986bc || $actual == 01ba35c8cbc3874f3a7fff3a7fd635abf0bb7e44d3633ce16a55a83b98ed09eb ]] || fail 'installed helper differs from qualified baseline or r1'
old_sha=$actual
parent=/var/lib/pf-console-boot/helper-backups
[[ ! -L $parent ]] || fail 'unexpected backup symlink'
mkdir -p "$parent"
work=$(mktemp -d "$parent/upstream-power-XXXXXXXX")
base64 -d > "$work/new-helper" <<'PF_UPSTREAM_HELPER'

PF_UPSTREAM_HELPER
printf '%s  %s\n' '34bb6e63e4553cb3ae9ee3e5be2ed3e05c7a8a18376acf73bc44dadc6ee72261' "$work/new-helper" | sha256sum -c -
bash -n "$work/new-helper"
cp -p -- "$target" "$work/previous-helper"
printf '%s  %s\n' "$old_sha" "$work/previous-helper" | sha256sum -c -
sync -f "$work"
temporary=$(mktemp /usr/local/sbin/.pf-console-boot-XXXXXXXX)
cp -- "$work/new-helper" "$temporary"
chmod 0755 "$temporary"
chown 0:0 "$temporary"
printf '%s  %s\n' '34bb6e63e4553cb3ae9ee3e5be2ed3e05c7a8a18376acf73bc44dadc6ee72261' "$temporary" | sha256sum -c -
sync -f "$temporary"
printf '%s  %s\n' "$old_sha" "$target" | sha256sum -c -
mv -T -- "$temporary" "$target"
sync -f /usr/local/sbin
printf 'COMPLETE helper=%s\n' '34bb6e63e4553cb3ae9ee3e5be2ed3e05c7a8a18376acf73bc44dadc6ee72261' > "$work/status"
sync -f "$work"
echo PF_UPSTREAM_RUNTIME_INSTALLED
